#!/usr/bin/env node
var request=require("request"),fs=require("fs"),uvheadloc="https://raw.github.com/joyent/libuv/master/include/uv.h",defreg=/^\s*XX\(\s*([\-\d]+),\s*([A-Z]+),\s*"([^"]*)"\s*\)\s*\\?$/;request(uvheadloc,function(e,n){if(e)throw e;var r,o;r=n.body.split("\n").map(function(e){return e.match(defreg)}).filter(function(e){return e}).map(function(e){return{errno:parseInt(e[1],10),code:e[2],description:e[3]}}),o="var all = module.exports.all = "+JSON.stringify(r,0,1)+"\n\n",o+="\nmodule.exports.errno = {\n    "+r.map(function(e,n){return"'"+e.errno+"': all["+n+"]"}).join("\n  , ")+"\n}\n\n",o+="\nmodule.exports.code = {\n    "+r.map(function(e,n){return"'"+e.code+"': all["+n+"]"}).join("\n  , ")+"\n}\n\n",o+='\nmodule.exports.custom = require("./custom")(module.exports)\n',fs.writeFile("errno.js",o)});